1	import { useState, useMemo, useEffect, useCallback } from "react";
2	import { supabase } from "@/integrations/supabase/client";
3	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
4	import { Badge } from "@/components/ui/badge";
5	import { Button } from "@/components/ui/button";
6	import { Input } from "@/components/ui/input";
7	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { Checkbox } from "@/components/ui/checkbox";
10	import { cn } from "@/lib/utils";
11	import {
12	  Search,
13	  ChevronRight,
14	  Briefcase,
15	  Code2,
16	  Palette,
17	  Users,
18	  BarChart2,
19	  Settings,
20	  Megaphone,
21	  FlaskConical,
22	  ArrowUpDown,
23	  Trash2,
24	  X,
25	  AlertTriangle,
26	  Download,
27	} from "lucide-react";
28	import { format } from "date-fns";
29	import { toast } from "sonner";
30	import type { PastJob } from "@/pages/Index";
31	
32	// ─── Types ───────────────────────────────────────────────────────────────────
33	
34	interface JobsOverviewCardProps {
35	  jobs: PastJob[];
36	  loading: boolean;
37	  onSelectJob: (jobId: string) => void;
38	  onDeleteJobs?: (jobIds: string[]) => Promise<void>;
39	}
40	
41	type SortOption = "latest" | "oldest" | "name_asc" | "name_desc" | "resumes_desc" | "score_desc";
42	
43	// ─── Helpers ─────────────────────────────────────────────────────────────────
44	
45	const PAGE_SIZE = 10;
46	
47	const JOB_ICONS = [Briefcase, Code2, Palette, Users, BarChart2, Settings, Megaphone, FlaskConical];
48	
49	const ICON_BG_COLORS = [
50	  "bg-blue-100 text-blue-600",
51	  "bg-violet-100 text-violet-600",
52	  "bg-pink-100 text-pink-600",
53	  "bg-amber-100 text-amber-600",
54	  "bg-teal-100 text-teal-600",
55	  "bg-orange-100 text-orange-600",
56	  "bg-emerald-100 text-emerald-600",
57	  "bg-indigo-100 text-indigo-600",
58	];
59	
60	function getJobIconProps(title: string | null, index: number) {
61	  const lower = (title ?? "").toLowerCase();
62	  let iconIndex = index % JOB_ICONS.length;
63	
64	  if (lower.includes("engineer") || lower.includes("developer") || lower.includes("dev") || lower.includes("code")) {
65	    iconIndex = 1;
66	  } else if (lower.includes("design") || lower.includes("ui") || lower.includes("ux")) {
67	    iconIndex = 2;
68	  } else if (lower.includes("manager") || lower.includes("hr") || lower.includes("talent") || lower.includes("recrui")) {
69	    iconIndex = 3;
70	  } else if (lower.includes("analyt") || lower.includes("data") || lower.includes("scientist")) {
71	    iconIndex = 4;
72	  } else if (lower.includes("market") || lower.includes("growth") || lower.includes("content")) {
73	    iconIndex = 6;
74	  } else if (lower.includes("research") || lower.includes("science") || lower.includes("lab")) {
75	    iconIndex = 7;
76	  }
77	
78	  return {
79	    Icon: JOB_ICONS[iconIndex],
80	    colorClass: ICON_BG_COLORS[iconIndex],
81	  };
82	}
83	
84	function extractEmploymentTags(jdAnalysis: any): string[] {
85	  if (!jdAnalysis) return [];
86	  const tags: string[] = [];
87	
88	  const empType =
89	    jdAnalysis.employment_type ??
90	    jdAnalysis.job_type ??
91	    jdAnalysis.type ??
92	    jdAnalysis.contract_type ??
93	    null;
94	
95	  const workType =
96	    jdAnalysis.work_type ??
97	    jdAnalysis.location_type ??
98	    jdAnalysis.remote ??
99	    jdAnalysis.work_arrangement ??
100	    null;
101	
102	  if (empType && typeof empType === "string") tags.push(empType);
103	  if (workType && typeof workType === "string") tags.push(workType);
104	
105	  return tags.filter(Boolean).map((t) => t.charAt(0).toUpperCase() + t.slice(1).toLowerCase());
106	}
107	
108	function scoreColor(score: number): string {
109	  if (score >= 70) return "#22c55e";
110	  if (score >= 40) return "#f59e0b";
111	  return "#ef4444";
112	}
113	
114	// ─── Circular Score Ring ─────────────────────────────────────────────────────
115	
116	interface CircularScoreProps {
117	  score: number | null;
118	  size?: number;
119	  strokeWidth?: number;
120	}
121	
122	const CircularScore = ({ score, size = 44, strokeWidth = 4 }: CircularScoreProps) => {
123	  if (score === null) {
124	    return (
125	      <span className="text-sm font-medium text-muted-foreground w-[44px] flex items-center justify-center">
126	        —
127	      </span>
128	    );
129	  }
130	
131	  const radius = (size - strokeWidth) / 2;
132	  const circumference = 2 * Math.PI * radius;
133	  const progress = Math.min(Math.max(score, 0), 100);
134	  const dashOffset = circumference - (progress / 100) * circumference;
135	  const color = scoreColor(progress);
136	
137	  return (
138	    <div className="relative flex items-center justify-center" style={{ width: size, height: size }}>
139	      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="-rotate-90">
140	        <circle
141	          cx={size / 2}
142	          cy={size / 2}
143	          r={radius}
144	          fill="none"
145	          stroke="currentColor"
146	          strokeWidth={strokeWidth}
147	          className="text-muted/30"
148	        />
149	        <circle
150	          cx={size / 2}
151	          cy={size / 2}
152	          r={radius}
153	          fill="none"
154	          stroke={color}
155	          strokeWidth={strokeWidth}
156	          strokeDasharray={circumference}
157	          strokeDashoffset={dashOffset}
158	          strokeLinecap="round"
159	        />
160	      </svg>
161	      <span
162	        className="absolute text-[10px] font-bold tabular-nums"
163	        style={{ color }}
164	      >
165	        {Math.round(progress)}%
166	      </span>
167	    </div>
168	  );
169	};
170	
171	// ─── Skeleton Row ─────────────────────────────────────────────────────────────
172	
173	const SkeletonRow = () => (
174	  <tr className="border-b border-border last:border-0">
175	    {[1, 2, 3, 4, 5, 6, 7].map((i) => (
176	      <td key={i} className="px-4 py-3.5">
177	        <Skeleton className="h-4 w-full rounded" />
178	      </td>
179	    ))}
180	  </tr>
181	);
182	
183	// ─── Bulk Action Bar ──────────────────────────────────────────────────────────
184	
185	interface BulkActionBarProps {
186	  count: number;
187	  onClear: () => void;
188	  onDelete: () => void;
189	  onExport: () => void;
190	  deleting: boolean;
191	}
192	
193	const BulkActionBar = ({ count, onClear, onDelete, onExport, deleting }: BulkActionBarProps) => (
194	  <div className="flex items-center justify-between gap-3 px-6 py-3 bg-primary/5 border-b border-primary/20 animate-in slide-in-from-top-1 duration-150">
195	    <div className="flex items-center gap-2.5">
196	      <div className="h-5 w-5 rounded-full bg-primary flex items-center justify-center">
197	        <span className="text-[10px] font-bold text-primary-foreground">{count}</span>
198	      </div>
199	      <span className="text-sm font-medium text-foreground">
200	        {count} job{count !== 1 ? "s" : ""} selected
201	      </span>
202	    </div>
203	
204	    <div className="flex items-center gap-2">
205	      <Button
206	        variant="outline"
207	        size="sm"
208	        className="h-8 gap-1.5 text-xs"
209	        onClick={onExport}
210	      >
211	        <Download className="h-3.5 w-3.5" />
212	        Export CSV
213	      </Button>
214	      <Button
215	        variant="outline"
216	        size="sm"
217	        className="h-8 gap-1.5 text-xs border-destructive/40 text-destructive hover:bg-destructive hover:text-destructive-foreground hover:border-destructive"
218	        onClick={onDelete}
219	        disabled={deleting}
220	      >
221	        <Trash2 className="h-3.5 w-3.5" />
222	        {deleting ? "Deleting…" : "Delete"}
223	      </Button>
224	      <button
225	        onClick={onClear}
226	        className="h-8 w-8 flex items-center justify-center rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
227	        aria-label="Clear selection"
228	      >
229	        <X className="h-3.5 w-3.5" />
230	      </button>
231	    </div>
232	  </div>
233	);
234	
235	// ─── Delete Confirm Dialog ────────────────────────────────────────────────────
236	
237	interface DeleteConfirmProps {
238	  count: number;
239	  onConfirm: () => void;
240	  onCancel: () => void;
241	  deleting: boolean;
242	}
243	
244	const DeleteConfirmBanner = ({ count, onConfirm, onCancel, deleting }: DeleteConfirmProps) => (
245	  <div className="flex items-center justify-between gap-3 px-6 py-3 bg-destructive/5 border-b border-destructive/20 animate-in slide-in-from-top-1 duration-150">
246	    <div className="flex items-center gap-2.5">
247	      <AlertTriangle className="h-4 w-4 text-destructive shrink-0" />
248	      <span className="text-sm font-medium text-destructive">
249	        Delete {count} job{count !== 1 ? "s" : ""}? This cannot be undone.
250	      </span>
251	    </div>
252	    <div className="flex items-center gap-2">
253	      <Button variant="outline" size="sm" className="h-8 text-xs" onClick={onCancel} disabled={deleting}>
254	        Cancel
255	      </Button>
256	      <Button variant="destructive" size="sm" className="h-8 text-xs gap-1.5" onClick={onConfirm} disabled={deleting}>
257	        <Trash2 className="h-3.5 w-3.5" />
258	        {deleting ? "Deleting…" : "Yes, Delete"}
259	      </Button>
260	    </div>
261	  </div>
262	);
263	
264	// ─── Main Component ───────────────────────────────────────────────────────────
265	
266	const JobsOverviewCard = ({ jobs, loading, onSelectJob, onDeleteJobs }: JobsOverviewCardProps) => {
267	  const [search, setSearch] = useState("");
268	  const [statusFilter, setStatusFilter] = useState<string>("all");
269	  const [sortOption, setSortOption] = useState<SortOption>("latest");
270	  const [page, setPage] = useState(1);
271	  const [avgScores, setAvgScores] = useState<Record<string, number>>({});
272	
273	  // Bulk select state
274	  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
275	  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
276	  const [deleting, setDeleting] = useState(false);
277	
278	  // Fetch average scores for all jobs
279	  useEffect(() => {
280	    if (jobs.length === 0) return;
281	    const jobIds = jobs.map((j) => j.id);
282	
283	    supabase
284	      .from("results")
285	      .select("job_id, overall_score")
286	      .in("job_id", jobIds)
287	      .then(({ data }) => {
288	        if (!data) return;
289	        const grouped: Record<string, number[]> = {};
290	        for (const row of data) {
291	          if (row.job_id && row.overall_score != null) {
292	            if (!grouped[row.job_id]) grouped[row.job_id] = [];
293	            grouped[row.job_id].push(row.overall_score);
294	          }
295	        }
296	        const averages: Record<string, number> = {};
297	        for (const [jobId, scores] of Object.entries(grouped)) {
298	          averages[jobId] = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
299	        }
300	        setAvgScores(averages);
301	      });
302	  }, [jobs]);
303	
304	  // Reset page + selection when filters change
305	  useEffect(() => {
306	    setPage(1);
307	    setSelectedIds(new Set());
308	    setShowDeleteConfirm(false);
309	  }, [search, statusFilter, sortOption]);
310	
311	  const filtered = useMemo(() => {
312	    let list = [...jobs];
313	
314	    if (search.trim()) {
315	      const q = search.toLowerCase();
316	      list = list.filter((j) => (j.title ?? "").toLowerCase().includes(q));
317	    }
318	
319	    if (statusFilter !== "all") {
320	      list = list.filter((j) => j.status === statusFilter);
321	    }
322	
323	    list.sort((a, b) => {
324	      switch (sortOption) {
325	        case "latest":
326	          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
327	        case "oldest":
328	          return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
329	        case "name_asc":
330	          return (a.title ?? "").localeCompare(b.title ?? "");
331	        case "name_desc":
332	          return (b.title ?? "").localeCompare(a.title ?? "");
333	        case "resumes_desc":
334	          return b.resume_count - a.resume_count;
335	        case "score_desc": {
336	          const sa = avgScores[a.id] ?? -1;
337	          const sb = avgScores[b.id] ?? -1;
338	          return sb - sa;
339	        }
340	        default:
341	          return 0;
342	      }
343	    });
344	
345	    return list;
346	  }, [jobs, search, statusFilter, sortOption, avgScores]);
347	
348	  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
349	  const paginated = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
350	  const startIndex = filtered.length === 0 ? 0 : (page - 1) * PAGE_SIZE + 1;
351	  const endIndex = Math.min(page * PAGE_SIZE, filtered.length);
352	
353	  // Bulk select helpers
354	  const pageIds = paginated.map((j) => j.id);
355	  const allPageSelected = pageIds.length > 0 && pageIds.every((id) => selectedIds.has(id));
356	  const somePageSelected = pageIds.some((id) => selectedIds.has(id));
357	
358	  const toggleSelectAll = useCallback(() => {
359	    setSelectedIds((prev) => {
360	      const next = new Set(prev);
361	      if (allPageSelected) {
362	        pageIds.forEach((id) => next.delete(id));
363	      } else {
364	        pageIds.forEach((id) => next.add(id));
365	      }
366	      return next;
367	    });
368	    setShowDeleteConfirm(false);
369	  }, [allPageSelected, pageIds]);
370	
371	  const toggleRow = useCallback((id: string, e: React.MouseEvent) => {
372	    e.stopPropagation();
373	    setSelectedIds((prev) => {
374	      const next = new Set(prev);
375	      if (next.has(id)) next.delete(id);
376	      else next.add(id);
377	      return next;
378	    });
379	    setShowDeleteConfirm(false);
380	  }, []);
381	
382	  const clearSelection = useCallback(() => {
383	    setSelectedIds(new Set());
384	    setShowDeleteConfirm(false);
385	  }, []);
386	
387	  const handleExportCSV = useCallback(() => {
388	    const selectedJobs = jobs.filter((j) => selectedIds.has(j.id));
389	    const header = ["Title", "Status", "Resumes", "Avg Score", "Created At"];
390	    const rows = selectedJobs.map((j) => [
391	      `"${(j.title ?? "Untitled Job").replace(/"/g, '""')}"`,
392	      j.status,
393	      j.resume_count,
394	      avgScores[j.id] != null ? `${avgScores[j.id]}%` : "—",
395	      format(new Date(j.created_at), "yyyy-MM-dd"),
396	    ]);
397	    const csv = [header.join(","), ...rows.map((r) => r.join(","))].join("\n");
398	    const blob = new Blob([csv], { type: "text/csv" });
399	    const url = URL.createObjectURL(blob);
400	    const a = document.createElement("a");
401	    a.href = url;
402	    a.download = `rankora-jobs-${format(new Date(), "yyyy-MM-dd")}.csv`;
403	    a.click();
404	    URL.revokeObjectURL(url);
405	    toast.success(`Exported ${selectedJobs.length} job${selectedJobs.length !== 1 ? "s" : ""}`);
406	  }, [jobs, selectedIds, avgScores]);
407	
408	  const handleDeleteConfirmed = useCallback(async () => {
409	    if (!onDeleteJobs) return;
410	    setDeleting(true);
411	    try {
412	      await onDeleteJobs(Array.from(selectedIds));
413	      toast.success(`Deleted ${selectedIds.size} job${selectedIds.size !== 1 ? "s" : ""}`);
414	      setSelectedIds(new Set());
415	      setShowDeleteConfirm(false);
416	    } catch {
417	      toast.error("Failed to delete jobs. Please try again.");
418	    } finally {
419	      setDeleting(false);
420	    }
421	  }, [onDeleteJobs, selectedIds]);
422	
423	  return (
424	    <Card className="w-full shadow-sm border border-border rounded-xl overflow-hidden">
425	      {/* ── Header ── */}
426	      <CardHeader className="px-6 pt-5 pb-4 border-b border-border">
427	        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1">
428	          <div>
429	            <CardTitle className="text-base font-semibold text-foreground">Jobs Overview</CardTitle>
430	            <p className="text-sm text-muted-foreground mt-0.5">
431	              Track and manage all your job postings.
432	            </p>
433	          </div>
434	          <span className="text-xs text-muted-foreground font-medium tabular-nums hidden sm:block">
435	            {filtered.length} job{filtered.length !== 1 ? "s" : ""}
436	          </span>
437	        </div>
438	      </CardHeader>
439	
440	      <CardContent className="p-0">
441	        {/* ── Filter Bar ── */}
442	        <div className="flex flex-wrap items-center gap-2 px-6 py-3 border-b border-border bg-muted/20">
443	          {/* Search */}
444	          <div className="relative flex-1 min-w-[160px] max-w-[280px]">
445	            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
446	            <Input
447	              placeholder="Search jobs..."
448	              value={search}
449	              onChange={(e) => setSearch(e.target.value)}
450	              className="h-8 pl-8 text-sm bg-background"
451	            />
452	          </div>
453	
454	          {/* Status filter */}
455	          <Select value={statusFilter} onValueChange={setStatusFilter}>
456	            <SelectTrigger className="h-8 w-[130px] text-sm bg-background">
457	              <SelectValue placeholder="Status" />
458	            </SelectTrigger>
459	            <SelectContent>
460	              <SelectItem value="all">All Status</SelectItem>
461	              <SelectItem value="pending">Pending</SelectItem>
462	              <SelectItem value="processing">Processing</SelectItem>
463	              <SelectItem value="completed">Completed</SelectItem>
464	              <SelectItem value="failed">Failed</SelectItem>
465	            </SelectContent>
466	          </Select>
467	
468	          {/* Sort */}
469	          <Select value={sortOption} onValueChange={(v) => setSortOption(v as SortOption)}>
470	            <SelectTrigger className="h-8 w-[150px] text-sm bg-background">
471	              <ArrowUpDown className="h-3.5 w-3.5 mr-1.5 text-muted-foreground" />
472	              <SelectValue placeholder="Sort" />
473	            </SelectTrigger>
474	            <SelectContent>
475	              <SelectItem value="latest">Latest First</SelectItem>
476	              <SelectItem value="oldest">Oldest First</SelectItem>
477	              <SelectItem value="name_asc">Name A–Z</SelectItem>
478	              <SelectItem value="name_desc">Name Z–A</SelectItem>
479	              <SelectItem value="resumes_desc">Most Resumes</SelectItem>
480	              <SelectItem value="score_desc">Highest Score</SelectItem>
481	            </SelectContent>
482	          </Select>
483	        </div>
484	
485	        {/* ── Bulk Action Bar ── */}
486	        {selectedIds.size > 0 && !showDeleteConfirm && (
487	          <BulkActionBar
488	            count={selectedIds.size}
489	            onClear={clearSelection}
490	            onDelete={() => setShowDeleteConfirm(true)}
491	            onExport={handleExportCSV}
492	            deleting={deleting}
493	          />
494	        )}
495	
496	        {/* ── Delete Confirm Banner ── */}
497	        {showDeleteConfirm && (
498	          <DeleteConfirmBanner
499	            count={selectedIds.size}
500	            onConfirm={handleDeleteConfirmed}
501	            onCancel={() => setShowDeleteConfirm(false)}
502	            deleting={deleting}
503	          />
504	        )}
505	
506	        {/* ── Table ── */}
507	        <div className="overflow-x-auto">
508	          <table className="w-full text-sm">
509	            <thead>
510	              <tr className="border-b border-border bg-muted/10">
511	                {/* Select All Checkbox */}
512	                <th className="pl-5 pr-2 py-2.5 w-10">
513	                  <Checkbox
514	                    checked={allPageSelected}
515	                    onCheckedChange={toggleSelectAll}
516	                    aria-label="Select all on this page"
517	                    className={cn(somePageSelected && !allPageSelected && "opacity-50")}
518	                  />
519	                </th>
520	                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
521	                  Job Title
522	                </th>
523	                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
524	                  Resumes
525	                </th>
526	                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
527	                  Avg. Match Score
528	                </th>
529	                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
530	                  Status
531	                </th>
532	                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
533	                  Created On
534	                </th>
535	                <th className="px-4 py-2.5" />
536	              </tr>
537	            </thead>
538	            <tbody>
539	              {loading ? (
540	                Array.from({ length: 5 }).map((_, i) => <SkeletonRow key={i} />)
541	              ) : paginated.length === 0 ? (
542	                <tr>
543	                  <td colSpan={7} className="px-6 py-12 text-center text-sm text-muted-foreground">
544	                    {search || statusFilter !== "all"
545	                      ? "No jobs match your filters."
546	                      : "No jobs yet. Create your first job to get started."}
547	                  </td>
548	                </tr>
549	              ) : (
550	                paginated.map((job, idx) => {
551	                  const globalIdx = (page - 1) * PAGE_SIZE + idx;
552	                  const { Icon, colorClass } = getJobIconProps(job.title, globalIdx);
553	                  const tags = extractEmploymentTags(job.jd_analysis_json);
554	                  const avgScore = job.resume_count > 0 ? (avgScores[job.id] ?? null) : null;
555	                  const isSelected = selectedIds.has(job.id);
556	
557	                  return (
558	                    <tr
559	                      key={job.id}
560	                      className={cn(
561	                        "border-b border-border last:border-0 hover:bg-muted/30 cursor-pointer transition-colors group",
562	                        isSelected && "bg-primary/[0.04]"
563	                      )}
564	                      onClick={() => onSelectJob(job.id)}
565	                    >
566	                      {/* Checkbox */}
567	                      <td className="pl-5 pr-2 py-3.5" onClick={(e) => toggleRow(job.id, e)}>
568	                        <Checkbox
569	                          checked={isSelected}
570	                          onCheckedChange={() => {}}
571	                          aria-label={`Select ${job.title ?? "job"}`}
572	                          className="pointer-events-none"
573	                        />
